from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'backend' / 'src'))
from services.official_regulations import AREA_DEFINITIONS, MODULES, get_official_regulation, module_aliases  # noqa: E402


def quote(value: str | None) -> str:
    return 'NULL' if value is None else "'" + value.replace("'", "''") + "'"


def generate() -> str:
    statements = [
        '-- PO-2021 DML only. Does not update or delete user JSON, course attempts, or catalog rows.',
        '-- Generated by backend/scripts/generate_official_po_migration.py from official_regulations.py.',
        'PRAGMA foreign_keys = ON;',
        "UPDATE study_programs SET po_version='2021', notes=replace(COALESCE(notes,''), '22.07.2022', '2021 PO; signed 25.03.2021; first applicable WS 2021/22') WHERE code IN ('BSC_INFO_2021','BSC_BIOINFO_2021','BSC_MEDIENINFO_2021','BSC_MEDIZININFO_2021','MSC_INFO_2021','MSC_ML_2021');",
        "UPDATE examination_regulations SET notes=replace(COALESCE(notes,''), '22.07.2022', '2021 PO; signed 25.03.2021; first applicable WS 2021/22') WHERE code IN ('BSC_INFO','BSC_BIOINFO','BSC_MEDIENINFO','BSC_MEDIZININFO','MSC_INFO','MSC_ML');",
        "UPDATE regulation_versions SET version_label='2021', notes=replace(COALESCE(notes,''), '22.07.2022', '2021 PO; signed 25.03.2021; first applicable WS 2021/22') WHERE code IN ('BSC_INFO_2021','BSC_BIOINFO_2021','BSC_MEDIENINFO_2021','BSC_MEDIZININFO_2021','MSC_INFO_2021','MSC_ML_2021');",
    ]
    # Retire duplicate legacy modules before aliases/options are rebuilt from the verified module IDs.
    for legacy_code in ('INF1020', 'INF1120', 'INF2310', 'INF2410'):
        statements.extend([
            f"DELETE FROM regulation_course_mappings WHERE module_id IN (SELECT id FROM curriculum_modules WHERE module_code={quote(legacy_code)});",
            f"DELETE FROM course_curriculum_matches WHERE module_id IN (SELECT id FROM curriculum_modules WHERE module_code={quote(legacy_code)});",
            f"DELETE FROM module_study_area_options WHERE module_id IN (SELECT id FROM curriculum_modules WHERE module_code={quote(legacy_code)});",
            f"DELETE FROM curriculum_module_aliases WHERE module_id IN (SELECT id FROM curriculum_modules WHERE module_code={quote(legacy_code)});",
            f"UPDATE curriculum_modules SET module_code={quote(legacy_code + '_LEGACY')}, module_type='legacy_review', source_note='Superseded by official PO-2021 canonical module; no student evidence is keyed here.' WHERE module_code={quote(legacy_code)};",
        ])
    for code, areas in AREA_DEFINITIONS.items():
        valid_codes = ','.join(quote(area[0]) for area in areas)
        statements.append(
            f"UPDATE regulation_rule_groups SET group_type='legacy_review', required_ects=NULL, notes='Deprecated area: keep historical assignments for review; not eligible for new credit.' WHERE regulation_version_id=(SELECT id FROM regulation_versions WHERE code={quote(code)}) AND code NOT IN ({valid_codes});"
        )
        statements.append(
            f"UPDATE study_areas SET area_type='legacy_review', required_ects=NULL, source_note='Deprecated area: historical assignments require explicit review.' WHERE program_id=(SELECT id FROM study_programs WHERE code={quote(code)}) AND code NOT IN ({valid_codes});"
        )
        for index, (area, name, kind, credits, _) in enumerate(areas, 1):
            statements.append(
                'INSERT INTO regulation_rule_groups (regulation_version_id, study_area_id, code, name, group_type, required_ects, sort_order, notes) '
                f"SELECT rv.id, NULL, {quote(area)}, {quote(name)}, {quote(kind)}, {credits}, {index * 10}, {quote('Official special part §5; official-po-sources.json')} FROM regulation_versions rv WHERE rv.code={quote(code)} "
                f"ON CONFLICT(regulation_version_id,code) DO UPDATE SET name=excluded.name, group_type=excluded.group_type, required_ects=excluded.required_ects, sort_order=excluded.sort_order, notes=excluded.notes;"
            )
            if area != 'THESIS':
                statements.append(
                    'INSERT INTO study_areas (program_id,code,name,required_ects,area_type,sort_order,source_note) '
                    f"SELECT sp.id,{quote(area)},{quote(name)},{credits},{quote(kind)},{index * 10},{quote('Official PO-2021 §5; see docs/official-po-sources.json')} FROM study_programs sp WHERE sp.code={quote(code)} "
                    'ON CONFLICT(program_id,code) DO UPDATE SET name=excluded.name,required_ects=excluded.required_ects,area_type=excluded.area_type,sort_order=excluded.sort_order,source_note=excluded.source_note;'
                )
                statements.append(
                    'UPDATE regulation_rule_groups SET study_area_id=(SELECT sa.id FROM study_areas sa JOIN study_programs sp ON sp.id=sa.program_id WHERE sp.code='
                    f"{quote(code)} AND sa.code={quote(area)}) WHERE regulation_version_id=(SELECT id FROM regulation_versions WHERE code={quote(code)}) AND code={quote(area)};"
                )

    module_programs: dict[str, set[str]] = {}
    for program, areas in AREA_DEFINITIONS.items():
        for area, _, _, _, module_codes in areas:
            for module_code in module_codes.split():
                module_programs.setdefault(module_code, set()).add(program)
    for code in sorted(module_programs):
        title, ects, kind = MODULES[code]
        course_ects = 'NULL' if kind in {'pool', 'completion'} else str(ects)
        counted_ects = 'NULL' if kind in {'pool', 'completion'} else str(ects)
        level = 'master' if any(p.startswith('MSC_') for p in module_programs[code]) else 'bachelor'
        statements.append(
            'INSERT INTO curriculum_modules (module_code,title,ects,module_type,level,source_note) '
            f"VALUES ({quote(code)},{quote(title)},{course_ects},{quote(kind)},{quote(level)},{quote('Official PO-2021 module table; see docs/official-po-sources.json')}) "
            'ON CONFLICT(module_code) DO UPDATE SET title=excluded.title,ects=excluded.ects,module_type=excluded.module_type,level=excluded.level,source_note=excluded.source_note;'
        )
        for alias in module_aliases(code):
            normalized = ''.join(ch for ch in alias.upper() if ch.isalnum())
            statements.append(
                'INSERT INTO curriculum_module_aliases (module_id,alias,normalized_alias,alias_type,notes) '
                f"SELECT cm.id,{quote(alias)},{quote(normalized)},{quote('alma_number' if alias != code else 'module_code')},{quote('PO-2021 source alias')} FROM curriculum_modules cm WHERE cm.module_code={quote(code)} "
                'ON CONFLICT(module_id,normalized_alias) DO UPDATE SET alias=excluded.alias,alias_type=excluded.alias_type,notes=excluded.notes;'
            )
        for program in sorted(module_programs[code]):
            area = next(area for area, _, _, _, codes in AREA_DEFINITIONS[program] if code in codes.split())
            if area == 'THESIS':
                continue
            statements.append(
                'INSERT INTO module_study_area_options (module_id,study_area_id,ects_counted,status,source_note) '
                f"SELECT cm.id,sa.id,{counted_ects},{quote('required' if AREA_DEFINITIONS[program][next(i for i,row in enumerate(AREA_DEFINITIONS[program]) if row[0]==area)][2] == 'pflicht' else 'allowed')},{quote('Official PO-2021 §5; area requirement only; integrated übK is not additive')} FROM curriculum_modules cm JOIN study_areas sa ON sa.code={quote(area)} JOIN study_programs sp ON sp.id=sa.program_id WHERE cm.module_code={quote(code)} AND sp.code={quote(program)} "
                'ON CONFLICT(module_id,study_area_id,status) DO UPDATE SET ects_counted=excluded.ects_counted,source_note=excluded.source_note;'
            )
    # Existing ALMA category codes are joined on exact module/alias identity. User data is not keyed on catalog IDs.
    statements.append(
        "INSERT OR IGNORE INTO course_curriculum_matches (course_id,module_id,match_type,confidence,notes) "
        "SELECT DISTINCT f.course_id,cm.id,'category_code',0.9,'Official PO-2021 module alias' FROM course_fields f JOIN json_each(f.value) je JOIN curriculum_module_aliases a ON a.normalized_alias=upper(replace(replace(replace(je.value,'-',''),' ',''),'.','')) JOIN curriculum_modules cm ON cm.id=a.module_id WHERE f.key='_categories_json';"
    )
    statements.append(
        "INSERT OR IGNORE INTO course_curriculum_matches (course_id,module_id,match_type,confidence,notes) "
        "SELECT DISTINCT c.id,cm.id,'number_alias',0.9,'Official PO-2021 module alias' FROM courses c JOIN curriculum_module_aliases a ON a.normalized_alias=upper(replace(replace(replace(c.number,'-',''),' ',''),'.','')) JOIN curriculum_modules cm ON cm.id=a.module_id WHERE c.number IS NOT NULL;"
    )
    return '\n\n'.join(statements) + '\n'


if __name__ == '__main__':
    output = ROOT / 'backend' / 'migrations' / '0040_official_po_credit_policies.sql'
    output.write_text(generate(), encoding='utf-8')
    print(f'Wrote {output}')
